#!/usr/bin/env python3
"""CUMNOISE1 analysis (planned/CUMNOISE1_PREREG.md)."""
import json, glob, statistics as st
R = [json.loads(l) for f in glob.glob('out/cumnoise1/*.jsonl') for l in open(f) if l.strip()]
M, OPS = ('houston', 'dfw'), ('wing', 'zipline', 'amazon')
rows = lambda m, v: sorted([r for r in R if r['metro'] == m and r['vol'] == v], key=lambda r: r['seed'])
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
fmt = lambda xs: '/'.join(str(x) for x in xs)
chk('N1', all(r['ge']['2300'] == 0 for m in M for r in rows(m, 'FILED')), '; '.join(f'{m} FILED max combined {fmt([r["dist"]["all"]["max"] for r in rows(m, "FILED")])}, receivers >= 2,300: {fmt([r["ge"]["2300"] for r in rows(m, "FILED")])}' for m in M))
chk('N2', all(r['ge']['1150'] == 0 for m in M for r in rows(m, 'FILED')), '; '.join(f'{m} FILED receivers >= 1,150: {fmt([r["ge"]["1150"] for r in rows(m, "FILED")])}' for m in M))
chk('N3', all(r['ge']['2300'] == 0 for m in M for r in rows(m, 'CAP')), '; '.join(f'{m} CAP max combined {fmt([r["dist"]["all"]["max"] for r in rows(m, "CAP")])}, receivers >= 2,300: {fmt([r["ge"]["2300"] for r in rows(m, "CAP")])}' for m in M))
med = lambda xs: st.median(xs)
chk('N4', all(med([r['dnl']['max'] for r in rows(m, 'FILED')]) < 50 and med([r['dnl']['max78'] for r in rows(m, 'FILED')]) < 65 for m in M),
    '; '.join(f'{m} FILED max en route DNL filed SELs {med([r["dnl"]["max"] for r in rows(m, "FILED")]):.1f} dB, all at 78.4 dB {med([r["dnl"]["max78"] for r in rows(m, "FILED")]):.1f} dB' for m in M))
sh = lambda r: r['reading2']['popOver1150'] / r['reading2']['popZone']
chk('N5', all(sh(r) >= 0.9 for m in M for r in rows(m, 'FILED')), '; '.join(f'{m} FILED people where covering hubs file > 1,150/day: {fmt([f"{100 * sh(r):.1f} %" for r in rows(m, "FILED")])}' for m in M))
s2 = lambda r: r['overflownBy']['two'] / r['overflownBy']['one'] if r['overflownBy']['one'] else 0
chk('N6', all(s2(r) >= 0.5 for m in M for r in rows(m, 'FILED')), '; '.join(f'{m} FILED overflown by 2+ companies: {fmt([f"{100 * s2(r):.0f} %" for r in rows(m, "FILED")])} of overflown receivers' for m in M))
npass = sum(1 for _, ok, _ in P if ok)
mean = lambda xs: sum(xs) / len(xs) if xs else float('nan')
L = ['# CUMNOISE1 results table (generated by planned/cumnoise1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Rows: {len(R)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Daily overflights per 50 m receiver (receivers more than 200 m from every site; mean over seeds)', '', '| Metro | Volume | Flights a day (W / Z / A) | Combined max | 99.9th | 99th | Median overflown | Wing max | Zipline max | Amazon max |', '|---|---|---|---|---|---|---|---|---|---|']
for m in M:
    for v in ('FILED', 'CAP'):
        x = rows(m, v)
        if not x: continue
        L.append(f'| {m} | {v} | ' + ' / '.join(f'{mean([r["flights"][op] for r in x]):.0f}' for op in OPS) + ' | ' + ' | '.join(f'{mean([r["dist"]["all"][q] for r in x]):.0f}' for q in ('max', 'p999', 'p99', 'p50')) + ' | ' + ' | '.join(f'{mean([r["dist"][op]["max"] for r in x]):.0f}' for op in OPS) + ' |')
L += ['', '## Receivers at or above the PEA lines (sum over seeds; "only combined" = above the line only when companies are added)', '', '| Metro | Volume | >= 100 | >= 500 | >= 1,150 | >= 2,300 | >= 100 only combined | >= 500 only combined |', '|---|---|---|---|---|---|---|---|']
for m in M:
    for v in ('FILED', 'CAP'):
        x = rows(m, v)
        if not x: continue
        L.append(f'| {m} | {v} | ' + ' | '.join(str(sum(r['ge'][t] for r in x)) for t in ('100', '500', '1150', '2300')) + ' | ' + ' | '.join(str(sum(r['geOnly'][t] for r in x)) for t in ('100', '500')) + ' |')
L += ['', '## En route DNL and shared airspace (mean over seeds)', '', '| Metro | Volume | Max DNL, filed SELs | Max DNL, all 78.4 dB | Receivers >= 45 dB | People >= 45 dB | Overflown by 2+ companies | by 3 | People in cells overflown by 2+ | Reading 2: people where covering hubs file > 1,150/day | Reading 2 median deliveries covering a 1 km square |', '|---|---|---|---|---|---|---|---|---|---|---|']
for m in M:
    for v in ('FILED', 'CAP'):
        x = rows(m, v)
        if not x: continue
        L.append(f'| {m} | {v} | {mean([r["dnl"]["max"] for r in x]):.1f} | {mean([r["dnl"]["max78"] for r in x]):.1f} | {mean([r["dnl"]["ge45"] for r in x]):.0f} | {mean([r["dnl"]["pop45"] for r in x]):.0f} | {100 * mean([s2(r) for r in x]):.0f} % | {100 * mean([r["overflownBy"]["three"] / r["overflownBy"]["one"] for r in x]):.0f} % | {mean([r["popOverflown2"] for r in x]):.0f} | {100 * mean([sh(r) for r in x]):.1f} % of {mean([r["reading2"]["popZone"] for r in x]):.0f} | {mean([r["reading2"]["median"] for r in x]):.0f} |')
L += ['', '## Busiest receivers (seed 1)', '']
for m in M:
    for v in ('FILED', 'CAP'):
        x = [r for r in rows(m, v) if r['seed'] == 1]
        for t in (x[0]['top'][:3] if x else []):
            L.append(f'- {m} {v}: {t["tot"]} overflights a day (Wing {t["byOp"]["wing"]}, Zipline {t["byOp"]["zipline"]}, Amazon {t["byOp"]["amazon"]}), en route DNL {t["dnl"]} dB, nearest site {t["nearestSite"]["op"]} at {t["nearestSite"]["m"]} m')
L += ['', '## Richardson check (DFW, Amazon overflights a day at receivers 1-3 km from STX8; context only)', '']
for v in ('FILED', 'CAP'):
    for r in rows('dfw', v):
        q = r['richardson']; L.append(f'- {v} seed {r["seed"]}: max {q["max"]}, 90th percentile {q["p90"]}, median {q["p50"]} ({q["overflown"]} of {q["receivers"]} receivers overflown)')
L += ['', '## Routing', '']
for m in M:
    x = rows(m, 'FILED')
    if x: s = {k: sum(r['stats'][k] for r in x) for k in x[0]['stats']}; L.append(f'- {m} FILED (3 seeds): flights {s["n"]}; airport detours {s["detour"]} ({100 * s["detour"] / s["n"]:.1f} %); straight through after 20 redraws {s["gaveUpAir"]} ({100 * s["gaveUpAir"] / s["n"]:.1f} %)')
open('planned/cumnoise1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
